"""Frozen pre-outer-wall transport receipts; expectations are never regenerated by tests."""
import copy
import hashlib
import json
from pathlib import Path
import platform
import sys

import numpy as np
import pandas as pd
import pytest

from mu2efastsim import materials
from trkfastsim.sim import fieldsteps as fs
from test_fieldsteps import _geometry, _lines, _start

SOURCE_SHA256 = "1570af163bdd0b1d622bc2fa3f926f8d4fb245bf23802c7c6f0628b88ab2cb9e"
RECEIPTS_PATH = Path(__file__).parent / "data" / "fieldwall_defaults.json"
CASES = {
    "muon_default": {"seed": 7101, "momentum": 150.0, "pdg": 13, "options": {}},
    "muon_tail_off": {"seed": 7102, "momentum": 150.0, "pdg": 13, "options": {"tail": False}},
    "muon_radiative": {"seed": 7103, "momentum": 50000.0, "pdg": 13, "options": {"radiative": True}},
    "electron_loss": {"seed": 7104, "momentum": 105.0, "pdg": 11, "options": {"tail": False}},
    "straws_off_vacuum": {"seed": 7105, "momentum": 150.0, "pdg": 13, "options": {"straws": False}},
    "straws_off_support": {"seed": 7106, "momentum": 150.0, "pdg": 13, "options": {"straws": False}},
}


def _json_bytes(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")


def _sha256(data):
    return hashlib.sha256(data).hexdigest()


def _frame_receipt(frame):
    """Hash schema plus C-order bytes of each column, retaining transport row order."""
    columns = []
    digest = hashlib.sha256()
    metadata = _json_bytes({"shape": list(frame.shape), "columns": list(frame.columns)})
    digest.update(len(metadata).to_bytes(8, "big"))
    digest.update(metadata)
    for name in frame.columns:
        values = frame[name].to_numpy()
        assert values.dtype.kind != "O" or len(values) == 0
        raw = values.tobytes(order="C")
        column = {"name": name, "dtype": values.dtype.str, "shape": list(values.shape), "sha256": _sha256(raw)}
        schema = _json_bytes(column)
        digest.update(len(schema).to_bytes(8, "big"))
        digest.update(schema)
        digest.update(len(raw).to_bytes(8, "big"))
        digest.update(raw)
        columns.append(column)
    index = frame.index.to_numpy()
    index_meta = {"dtype": index.dtype.str, "shape": list(index.shape), "sha256": _sha256(index.tobytes())}
    digest.update(_json_bytes(index_meta))
    return {"shape": list(frame.shape), "columns": columns, "index": index_meta, "sha256": digest.hexdigest()}


class _SlabSupport:
    """A finite Mylar slab in z, with analytic line-length moments along each chord."""

    def __init__(self):
        self.zlo, self.zhi = -12.0, -10.0

    def _support(self, x, direction, length, moments):
        dz = direction[:, 2]
        safe_dz = np.where(np.abs(dz) > 1e-15, dz, 1.0)
        a, b = (self.zlo - x[:, 2]) / safe_dz, (self.zhi - x[:, 2]) / safe_dz
        lo = np.clip(np.minimum(a, b), 0.0, length)
        hi = np.clip(np.maximum(a, b), 0.0, length)
        inside = (x[:, 2] >= self.zlo) & (x[:, 2] <= self.zhi)
        lo = np.where(np.abs(dz) > 1e-15, lo, 0.0)
        hi = np.where(np.abs(dz) > 1e-15, hi, np.where(inside, length, 0.0))
        amount = hi - lo
        name = materials.MYLAR.name
        return {name: amount}, {name: (amount, (hi ** 2 - lo ** 2) / 2, (hi ** 3 - lo ** 3) / 3)}


def _assert_unchanged(actual, expected):
    if isinstance(expected, pd.DataFrame):
        pd.testing.assert_frame_equal(actual, expected, check_exact=True)
    elif isinstance(expected, np.ndarray):
        np.testing.assert_array_equal(actual, expected)
        assert actual.dtype == expected.dtype
    elif isinstance(expected, dict):
        assert actual.keys() == expected.keys()
        for key in expected:
            _assert_unchanged(actual[key], expected[key])
    elif hasattr(expected, "__dict__"):
        _assert_unchanged(vars(actual), vars(expected))
    else:
        assert actual == expected


def _run_case(name, explicit_false=False):
    case = CASES[name]
    geom = _geometry()
    positions, directions = _lines(16, np.random.default_rng(7100))
    start = _start(positions, directions, case["momentum"], pdg=case["pdg"])
    field = np.array([0.0, 0.0, 1.0])
    origin = np.zeros(3)
    envelope = fs.Envelope(geom, pad_r=10.0, pad_z=10.0, axis_xy=(0.0, 0.0))
    interior = _SlabSupport() if name == "straws_off_support" else None
    inputs = {"start": start, "geom": geom, "field": field, "origin": origin, "envelope": envelope,
              "interior": interior, "positions": positions, "directions": directions}
    before = copy.deepcopy(inputs)
    options = dict(case["options"])
    if name == "electron_loss":
        options["loss"] = fs.electron_loss
    if explicit_false:
        options["complete_outer_wall"] = False
    rng = np.random.default_rng(case["seed"])
    initial_rng_sha256 = _sha256(_json_bytes(rng.bit_generator.state))
    try:
        sgsteps, final = fs.transport(rng, start, geom, field, interior, envelope=envelope, origin=origin,
                                      chord_mm=4.0, **options)
    finally:
        _assert_unchanged(inputs, before)
    return {"sgsteps": _frame_receipt(sgsteps), "final": _frame_receipt(final),
            "initial_rng_sha256": initial_rng_sha256,
            "final_rng_sha256": _sha256(_json_bytes(rng.bit_generator.state))}


@pytest.fixture(scope="module")
def frozen_receipts():
    receipts = json.loads(RECEIPTS_PATH.read_text())
    assert receipts["source_sha256"] == SOURCE_SHA256
    assert receipts["cases"] == CASES
    assert receipts["input"] == {"tracks": 16, "line_seed": 7100, "straws": 48, "chord_mm": 4.0,
                                 "field_T": [0.0, 0.0, 1.0], "origin_mm": [0.0, 0.0, 0.0]}
    environment = receipts["environment"]
    current = (platform.python_version(), np.__version__, pd.__version__, platform.system(), platform.machine(),
               sys.byteorder, np.random.default_rng().bit_generator.__class__.__name__)
    captured = (environment["python"].split()[0], environment["numpy"], environment["pandas"], "Darwin",
                environment["machine"], environment["byteorder"], environment["bit_generator"])
    if current != captured:
        pytest.skip("pre-edit byte receipts require their captured platform/dependency versions")
    return receipts


@pytest.mark.parametrize("name", CASES)
def test_default_and_false_match_on_current_platform(name):
    assert _run_case(name) == _run_case(name, explicit_false=True)


@pytest.mark.parametrize("name", CASES)
def test_default_matches_frozen_receipts(name, frozen_receipts):
    assert _run_case(name) == frozen_receipts["receipts"][name]


@pytest.mark.parametrize("name", CASES)
def test_explicit_false_matches_frozen_receipts(name, frozen_receipts):
    assert _run_case(name, explicit_false=True) == frozen_receipts["receipts"][name]
